-- Reversal journal (REVERSAL-001, F20; CONTEXT_PACK §7, §8.3, §8.6). Generated by `pnpm db:generate --name
-- reversal_journal_entries` from src/schema/reversal-journal.ts, then reviewed. Forward-only: never edit once applied.
-- One row per state_changing action, written before it runs. Inline target and undo_instructions are capped at 16 KiB
-- (CHECK). Composite (tenant_id, …) foreign keys stop an entry naming another tenant's run or case. The
-- test_cases (tenant_id, id) unique constraint is the target of the case foreign key.
CREATE TABLE "reversal_journal_entries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"public_id" text NOT NULL,
	"tenant_id" uuid NOT NULL,
	"run_id" uuid NOT NULL,
	"test_case_id" uuid NOT NULL,
	"subtask_id" uuid,
	"action" text NOT NULL,
	"target" jsonb NOT NULL,
	"intrusiveness_class" text DEFAULT 'state_changing' NOT NULL,
	"undo_instructions" jsonb NOT NULL,
	"undo_status" text DEFAULT 'pending' NOT NULL,
	"undo_attempts" integer DEFAULT 0 NOT NULL,
	"undone_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "reversal_journal_entries_public_id_check" CHECK (starts_with("reversal_journal_entries"."public_id", 'rvj_')),
	CONSTRAINT "reversal_journal_entries_action_check" CHECK (char_length("reversal_journal_entries"."action") BETWEEN 1 AND 200),
	CONSTRAINT "reversal_journal_entries_intrusiveness_check" CHECK ("reversal_journal_entries"."intrusiveness_class" = 'state_changing'),
	CONSTRAINT "reversal_journal_entries_undo_status_check" CHECK ("reversal_journal_entries"."undo_status" IN ('pending', 'undone', 'not_needed', 'failed')),
	CONSTRAINT "reversal_journal_entries_undo_attempts_check" CHECK ("reversal_journal_entries"."undo_attempts" >= 0),
	CONSTRAINT "reversal_journal_entries_undone_at_check" CHECK ("reversal_journal_entries"."undo_status" = 'undone' OR "reversal_journal_entries"."undone_at" IS NULL),
	CONSTRAINT "reversal_journal_entries_target_object_check" CHECK (jsonb_typeof("reversal_journal_entries"."target") = 'object' AND octet_length("reversal_journal_entries"."target"::text) <= 16384),
	CONSTRAINT "reversal_journal_entries_undo_object_check" CHECK (jsonb_typeof("reversal_journal_entries"."undo_instructions") = 'object' AND octet_length("reversal_journal_entries"."undo_instructions"::text) <= 16384)
);
--> statement-breakpoint
ALTER TABLE "reversal_journal_entries" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "test_cases" ADD CONSTRAINT "test_cases_tenant_id_id_unique" UNIQUE("tenant_id","id");--> statement-breakpoint
-- NOT VALID: `runs` and `test_cases` are already FORCE ROW LEVEL SECURITY, so validating these keys against existing
-- rows would run the tenant policy as the owner with no tenant set. The table is created empty here, so there is nothing
-- to validate; every later insert and update is still checked by the keys.
ALTER TABLE "reversal_journal_entries" ADD CONSTRAINT "reversal_journal_entries_run_fk" FOREIGN KEY ("tenant_id","run_id") REFERENCES "public"."runs"("tenant_id","id") ON DELETE no action ON UPDATE no action NOT VALID;--> statement-breakpoint
ALTER TABLE "reversal_journal_entries" ADD CONSTRAINT "reversal_journal_entries_test_case_fk" FOREIGN KEY ("tenant_id","test_case_id") REFERENCES "public"."test_cases"("tenant_id","id") ON DELETE no action ON UPDATE no action NOT VALID;--> statement-breakpoint
CREATE INDEX "reversal_journal_entries_tenant_id_idx" ON "reversal_journal_entries" USING btree ("tenant_id");--> statement-breakpoint
CREATE INDEX "reversal_journal_entries_tenant_run_idx" ON "reversal_journal_entries" USING btree ("tenant_id","run_id");--> statement-breakpoint
CREATE INDEX "reversal_journal_entries_run_undo_status_idx" ON "reversal_journal_entries" USING btree ("run_id","undo_status");--> statement-breakpoint
CREATE INDEX "reversal_journal_entries_test_case_id_idx" ON "reversal_journal_entries" USING btree ("test_case_id");--> statement-breakpoint
CREATE UNIQUE INDEX "reversal_journal_entries_public_id_key" ON "reversal_journal_entries" USING btree ("public_id");--> statement-breakpoint
CREATE POLICY "reversal_journal_entries_tenant_isolation" ON "reversal_journal_entries" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);

-- Hand-written below (Drizzle models neither FORCE ROW LEVEL SECURITY, grants nor the updated_at trigger). Reviewed.
-- FORCE: the owner role is subject to the tenant policy too, so nothing reads across tenants.
ALTER TABLE "reversal_journal_entries" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- The runtime role reads, journals and updates the undo status. It never deletes or truncates an entry: the journal
-- is the record that an undo was required (§8.8), so a row is closed (undone / not_needed / failed), never removed.
REVOKE ALL ON "reversal_journal_entries" FROM PUBLIC;--> statement-breakpoint
REVOKE DELETE, TRUNCATE ON "reversal_journal_entries" FROM bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "reversal_journal_entries" TO bw_app;--> statement-breakpoint
-- Keeps updated_at in step with every write (bw_set_updated_at: 0002_column_mixins). The repository guards its
-- status update on updated_at.
CREATE TRIGGER reversal_journal_entries_set_updated_at BEFORE UPDATE ON reversal_journal_entries FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();
